using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using System.Web.Script.Serialization;
public sealed class CatalogEntry {public string Id,Name,Version,Description,Package,Sha256;public bool Local;}
public sealed class CatalogDocument {public int Schema=1;public List<CatalogEntry> Plugins=new List<CatalogEntry>();}
public static class PluginCatalog {
 public static CatalogEntry[] Bundled(string folder){string index=Path.Combine(folder,"catalog.json");if(!File.Exists(index))return new CatalogEntry[0];byte[] data=File.ReadAllBytes(index);if(data.Length>262144||PluginManager.Hash(data)!=FirstPartyPackageHashes.Catalog)throw new InvalidDataException("随附插件目录校验失败。");var doc=new JavaScriptSerializer{MaxJsonLength=262144}.Deserialize<CatalogDocument>(System.Text.Encoding.UTF8.GetString(data));if(doc==null||doc.Schema!=1||doc.Plugins==null||doc.Plugins.Count>100)throw new InvalidDataException("随附插件目录格式错误。");var result=new List<CatalogEntry>();var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var entry in doc.Plugins){if(entry==null||!Regex.IsMatch(entry.Id??"","^[a-z][a-z0-9-]{2,39}$")||!ids.Add(entry.Id)||!Regex.IsMatch(entry.Package??"",@"^[a-z0-9.-]+\.conanplugin$")||!Regex.IsMatch(entry.Sha256??"","^[a-f0-9]{64}$"))throw new InvalidDataException("随附插件目录项目无效。");string path=Path.Combine(folder,entry.Package);if(!File.Exists(path))continue;if(new FileInfo(path).Length>128L*1024*1024||PluginManager.Hash(File.ReadAllBytes(path))!=entry.Sha256)throw new InvalidDataException("随附插件包校验失败。");var m=PluginManager.Inspect(path);if(m.Id!=entry.Id||m.Version!=entry.Version)throw new InvalidDataException("随附插件版本不一致。");entry.Name=m.Name;entry.Description=m.Description;entry.Package=path;entry.Local=true;result.Add(entry);}return result.ToArray();}
 public static CatalogEntry[] ParseRemote(string text){if(text==null||text.Length>262144)throw new InvalidDataException("插件目录超过大小限制。");var doc=new JavaScriptSerializer{MaxJsonLength=262144}.Deserialize<CatalogDocument>(text);if(doc==null||doc.Schema!=1||doc.Plugins==null||doc.Plugins.Count>100)throw new InvalidDataException("插件目录格式不受支持。");var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var entry in doc.Plugins){Version version;Uri uri;if(entry==null||!Regex.IsMatch(entry.Id??"","^[a-z][a-z0-9-]{2,39}$")||!ids.Add(entry.Id)||!Version.TryParse(entry.Version,out version)||version.Major<1||String.IsNullOrWhiteSpace(entry.Name)||entry.Name.Length>80||(entry.Description??"").Length>2000||!Regex.IsMatch(entry.Sha256??"","^[a-f0-9]{64}$")||!Uri.TryCreate(entry.Package,UriKind.Absolute,out uri)||uri.Scheme!="https"||!String.IsNullOrEmpty(uri.UserInfo))throw new InvalidDataException("插件目录中存在无效项目。");entry.Local=false;}return doc.Plugins.ToArray();}
 public static CatalogEntry[] Search(IEnumerable<CatalogEntry> entries,string text){string q=(text??"").Trim();return entries.Where(e=>q.Length==0||((e.Name??"")+" "+e.Id+" "+(e.Description??"")).IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0).OrderBy(e=>e.Name,StringComparer.OrdinalIgnoreCase).ToArray();}
 public static bool UpdateAvailable(CatalogEntry entry,PluginRow[] installed){var row=installed.FirstOrDefault(x=>x.Manifest.Id==entry.Id);Version current,available;return row!=null&&Version.TryParse(row.Manifest.Version,out current)&&Version.TryParse(entry.Version,out available)&&available>current;}
 public static void VerifyDownloaded(CatalogEntry entry,string path){if(new FileInfo(path).Length>128L*1024*1024||PluginManager.Hash(File.ReadAllBytes(path))!=entry.Sha256)throw new InvalidDataException("下载的插件包与目录校验值不一致。");var manifest=PluginManager.Inspect(path);if(manifest.Id!=entry.Id||manifest.Version!=entry.Version)throw new InvalidDataException("插件标识或版本与目录不一致。");}
}
